declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';use App\Services\Security\AdminPasswordResetService;use Config\Database;
$admin=Database::connect('default',false);if((string)$admin->query('SELECT DATABASE() name')->getRow()->name!=='ikontrol_new')throw new RuntimeException('Verified local connection required.');$name='ikontrol_admin_password_'.bin2hex(random_bytes(4));if(!preg_match('/^ikontrol_admin_password_[a-f0-9]{8}$/',$name))throw new RuntimeException('Unsafe test database name.');$quoted='`'.$name.'`';$passed=0;$assert=static function(bool$ok,string$message)use(&$passed):void{if(!$ok)throw new RuntimeException('[FAIL] '.$message);$passed++;echo'[PASS] '.$message.PHP_EOL;};
try{$admin->query("CREATE DATABASE {$quoted} CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci");$cfg=config('Database')->default;$cfg['database']=$name;$cfg['DBPrefix']='ikontrol_';$db=Database::connect($cfg,false);$db->query('CREATE TABLE `ikontrol_users` (`id` INT AUTO_INCREMENT PRIMARY KEY, `email` VARCHAR(255) NOT NULL, `password` VARCHAR(255) NULL, `user_type` VARCHAR(20) NOT NULL, `deleted` TINYINT NOT NULL DEFAULT 0)');$db->table('users')->insert(['email'=>'stage-admin@example.invalid','password'=>password_hash('old-local-value',PASSWORD_DEFAULT),'user_type'=>'staff','deleted'=>0]);$service=new AdminPasswordResetService($db);$newPassword='Stage-Sentinel-2026!';$result=$service->reset('stage-admin@example.invalid',$newPassword,$newPassword);$assert($result['id']===1,'Existing staff user resolved by exact email.');$stored=(string)$db->table('users')->select('password')->where('id',1)->get()->getRow()->password;$assert($stored!==$newPassword&&password_verify($newPassword,$stored),'Project-compatible password hash was stored, never plaintext.');foreach([['missing@example.invalid',$newPassword,$newPassword],['1','',''],['1','too-short','too-short'],['1',$newPassword,'different-value']]as$case){try{$service->reset(...$case);throw new RuntimeException('Invalid reset unexpectedly succeeded.');}catch(RuntimeException$e){$assert(!str_contains($e->getMessage(),$newPassword),'Invalid reset rejected without echoing the password.');}}$command=file_get_contents(APPPATH.'Commands/AdminResetPassword.php');$assert(!str_contains((string)$command,"'--password'")&&!str_contains((string)$command,'CLI::prompt'),'Command accepts no password option and uses hidden input.');echo"passed={$passed}\n";}finally{$admin->query("DROP DATABASE IF EXISTS {$quoted}");}
